function main(inputs) {
  const scores = inputs.scores || [];
  const grades = [];
  const counts = { A: 0, B: 0, C: 0, D: 0 };
  for (let i = 0; i < scores.length; i++) {
    const s = Number(scores[i]);
    let g;
    if (s >= 90) {
      g = "A";
    } else if (s >= 75) {
      g = "B";
    } else if (s >= 60) {
      g = "C";
    } else {
      g = "D";
    }
    grades.push(g);
    counts[g] += 1;
  }
  return { grades: grades, A: counts.A, B: counts.B, C: counts.C, D: counts.D };
}
